//! Where a module sits on the MasterHUB base, from the USB port chain it enumerates on.
//!
//! The base's connectors are fixed, and each one is a distinct port chain below the base's own hub. The slot table
//! (`data/base-slots.json`, generated by `scripts/extract-base-slots.mjs` from the geometry of the official app's base
//! drawing) maps a module class and that chain, relative to the hub, to the cell its footprint starts at.

use cooltek_sdk_service::ServiceModule;
use serde::Deserialize;
use std::{collections::HashMap, sync::OnceLock};

/// Where the base's own HID interface sits below its hub; it never moves, so it gives the hub's chain away.
const BASE_SLOT: [u8; 3] = [1, 4, 4];

#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq)]
pub struct Slot {
    pub col: i8,
    pub row: i8,
    /// Quarter turns the official drawing applies to the module in its own (portrait) frame; carried for module
    /// orientation (task 37), not used for placement.
    pub official_rotation: u16,
}

#[derive(Deserialize)]
struct Table {
    modules: HashMap<String, HashMap<String, Slot>>,
}

fn table() -> &'static Table {
    static TABLE: OnceLock<Table> = OnceLock::new();
    TABLE.get_or_init(|| {
        serde_json::from_str(include_str!("../data/base-slots.json"))
            .expect("data/base-slots.json is valid")
    })
}

/// Slots seen on a unit that the official drawing has no connector for (the module hung over the base's edge).
fn observed(module: &str, slot: &str) -> Option<Slot> {
    match (module, slot) {
        // 11 October 2026: the 15-key module's top row one cell above the base, over the faders.
        ("M4315", "111") => Some(Slot {
            col: 0,
            row: -1,
            official_rotation: 270,
        }),
        _ => None,
    }
}

fn module_key(module: ServiceModule) -> &'static str {
    match module {
        ServiceModule::M4315 => "M4315",
        ServiceModule::M032LE => "M032LE",
        ServiceModule::M005S => "M005S",
        ServiceModule::M131E => "M131E",
        ServiceModule::M003K => "M003K",
    }
}

/// The USB port chain of a macOS location ID: the ports below the bus, without the trailing zeros.
pub fn port_chain(location_id: u32) -> Vec<u8> {
    let mut ports: Vec<u8> = (0..6)
        .map(|index| ((location_id >> (20 - 4 * index)) & 0x0f) as u8)
        .collect();
    while ports.last() == Some(&0) {
        ports.pop();
    }
    ports
}

/// The chain of the base's hub, taken from the chain the base's own interface enumerates on.
pub fn hub_prefix(base_chain: &[u8]) -> Option<Vec<u8>> {
    let hub = base_chain.strip_suffix(&BASE_SLOT)?;
    (!hub.is_empty()).then(|| hub.to_vec())
}

/// The connector slot of a module: its chain below the hub, the port numbers written one after another.
pub fn slot_name(chain: &[u8], hub: &[u8]) -> Option<String> {
    let below = chain.strip_prefix(hub).filter(|below| !below.is_empty())?;
    Some(below.iter().map(|port| port.to_string()).collect())
}

pub fn lookup(module: ServiceModule, slot: &str) -> Option<Slot> {
    let key = module_key(module);
    table()
        .modules
        .get(key)
        .and_then(|slots| slots.get(slot))
        .copied()
        .or_else(|| observed(key, slot))
}

/// `chain` as dotted text for diagnostics, for example `1.1.2.3`.
pub fn chain_text(chain: &[u8]) -> String {
    chain
        .iter()
        .map(u8::to_string)
        .collect::<Vec<_>>()
        .join(".")
}

#[cfg(test)]
mod tests {
    use super::*;

    // The chains recorded in docs/masterhub-hardware-results.md, with the hub at 1.1 (base at 1.1.1.4.4).
    const HUB: [u8; 2] = [1, 1];
    fn at(module: ServiceModule, chain: &[u8]) -> Option<(i8, i8)> {
        lookup(module, &slot_name(chain, &HUB)?).map(|slot| (slot.col, slot.row))
    }

    #[test]
    fn the_hub_comes_from_the_bases_own_chain() {
        assert_eq!(hub_prefix(&[1, 1, 1, 4, 4]), Some(vec![1, 1]));
        assert_eq!(hub_prefix(&[2, 1, 1, 4, 4]), Some(vec![2, 1]));
        assert_eq!(hub_prefix(&[1, 4, 4]), None);
        assert_eq!(hub_prefix(&[1, 1, 2, 3]), None);
    }

    #[test]
    fn the_first_arrangement_is_placed_from_the_table() {
        assert_eq!(at(ServiceModule::M4315, &[1, 1, 2, 2]), Some((0, 0)));
        assert_eq!(at(ServiceModule::M032LE, &[1, 1, 1, 1, 4]), Some((0, 3)));
        assert_eq!(at(ServiceModule::M131E, &[1, 1, 1, 4, 3]), Some((4, 0)));
        assert_eq!(at(ServiceModule::M003K, &[1, 1, 1, 3, 4]), Some((4, 2)));
    }

    #[test]
    fn the_second_and_third_arrangements_are_placed_from_the_table() {
        assert_eq!(at(ServiceModule::M4315, &[1, 1, 2, 3]), Some((0, 1)));
        assert_eq!(at(ServiceModule::M005S, &[1, 1, 2, 3]), Some((0, 2)));
        assert_eq!(at(ServiceModule::M4315, &[1, 1, 1, 1, 1]), Some((0, -1)));
    }

    #[test]
    fn a_chain_outside_the_hub_or_not_in_the_table_is_not_placed() {
        assert_eq!(slot_name(&[2, 1, 2, 3], &HUB), None);
        assert_eq!(slot_name(&[1, 1], &HUB), None);
        assert_eq!(at(ServiceModule::M4315, &[1, 1, 9, 9]), None);
    }

    #[test]
    fn the_table_covers_every_module_and_stays_on_the_base() {
        for module in [
            ServiceModule::M4315,
            ServiceModule::M032LE,
            ServiceModule::M005S,
            ServiceModule::M131E,
            ServiceModule::M003K,
        ] {
            let slots = &table().modules[module_key(module)];
            assert!(slots.len() >= 10, "{module:?} has {} slots", slots.len());
            assert!(
                slots
                    .values()
                    .all(|slot| (-4..6).contains(&slot.col) && (-4..4).contains(&slot.row))
            );
            assert!(
                slots
                    .values()
                    .all(|slot| matches!(slot.official_rotation, 0 | 90 | 180 | 270))
            );
        }
    }

    #[test]
    fn a_location_id_reads_as_its_port_chain() {
        assert_eq!(port_chain(0x0211_2300), vec![1, 1, 2, 3]);
        assert_eq!(chain_text(&port_chain(0x0211_1110)), "1.1.1.1.1");
    }
}
